function BatteryCoachScreen({ vehicle, scenario }) {
  const rules = matchAdaptiveRules(scenario.adaptive_rules, vehicle);
  const [i, setI] = useState(0);
  const step = applyVariants(scenario.steps[i], vehicle);
  useEffect(() => emitFocus({ part: 'battery', action: step.id }), [step.id]);
  return (
    <CoachShell
      media={resolveAsset(scenario, step)}
      title={step.title}
      body={injectCoachNotes(step.description, rules)}
      safety={step.safety_warning}
      actions={step.action_buttons}
      onAction={(btn) => handleCoachAction(btn, { setI, scenario })}
    />
  );
}
